  const pHash=n=>{let h=0;for(let i=0;i<6;i++)h+=Math.sin(n*P[i]*0.0137)*(P[i]/29);return h/6;};
  const src=[
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
